atQTY (or OriginalQty)#(lf)    CASE #(lf)        WHEN o.PremiumFlag = 1 THEN o.CFFLAT_CC * o.FlatQTY #(lf)        ELSE o.CFFlat * o.OriginalQty #(lf)    END AS LineTotalCF_USD,#(lf)    #(lf)    -- Calculate LineTotalCF_NIS (apply DollarRate to the above)#(lf)    CASE #(lf)        WHEN o.PremiumFlag = 1 THEN o.CFFLAT_CC * o.FlatQTY * o.DollarRate #(lf)        ELSE o.CFFlat * o.DollarRate * o.OriginalQty #(lf)    END AS LineTotalCF_NIS,#(lf)    #(lf)    -- Calculate UnitPriceFOT based on the PremiumFlag#(lf)    CASE #(lf)        WHEN o.PremiumFlag = 1 THEN o.FOT_CC #(lf)        ELSE o.FotPrice #(lf)    END AS UnitPriceFOT,#(lf)    #(lf)    -- Calculate LineTotalFOT_USD using PremiumFlag and FlatQTY (or OriginalQty)#(lf)    CASE #(lf)        WHEN o.PremiumFlag = 1 THEN o.FOT_CC * o.FlatQTY #(lf)        ELSE o.FotPrice * o.OriginalQty #(lf)    END AS LineTotalFOT_USD,#(lf)    #(lf)    -- Calculate LineTotalFOT_NIS (apply DollarRate to the above)#(lf)    CASE #(lf)        WHEN o.PremiumFlag = 1 THEN o.FOT_CC * o.FlatQTY * o.DollarRate #(lf)        ELSE o.FotPrice * o.DollarRate * o.OriginalQty #(lf)    END AS LineTotalFOT_NIS,#(lf)    #(lf)    -- Use BasisQTY to compute the flat value balance in USD#(lf)    CASE#(lf)#(tab)#(tab)WHEN o.PremiumFlag = 1 THEN (o.POL_StockMarketTempPriceForNoneClosed * o.BasisQTY)+(o.FlatQTY * FinalPriceClosedContract) #(lf)#(tab)#(tab)ELSE LineTotalBalanceUSD#(lf)#(tab)#(tab)END AS LineTotalFlatValueBalanceUSD,#(lf)    #(lf)    -- Calculate MarketTempPriceCFF_USD and its related total using BasisQTY#(lf)    CASE #(lf)        WHEN o.PremiumFlag = 1 THEN o.CFFLAT_NCC #(lf)        ELSE NULL #(lf)    END AS MarketTempPriceCFF_USD,#(lf)    #(lf)    CASE #(lf)        WHEN o.PremiumFlag = 1 THEN (o.CFFLAT_NCC * o.BasisQTY) + (o.FlatQTY * o.CFFLAT_NCC)#(lf)        ELSE QuantityLeft*o.CFFlat #(lf)    END AS LineTotalFlatValueBalanceCFFUSD,#(lf)#(tab)CASE #(lf)        WHEN o.PremiumFlag = 1 THEN (o.FlatQTY * o.CFFLAT_NCC)#(lf)        ELSE QuantityLeft*o.CFFlat #(lf)    END AS LineTotalFlatBalanceCFFUSD,#(lf)    #(lf)    -- Calculate MarketTempPriceFOT_USD and its related total using BasisQTY#(lf)    CASE #(lf)        WHEN o.PremiumFlag = 1 THEN o.FOT_NCC #(lf)        ELSE NULL #(lf)    END AS MarketTempPriceFOT_USD,#(lf)    #(lf)    CASE #(lf)        WHEN o.PremiumFlag = 1 THEN  (o.FOT_NCC * o.BasisQTY) + (o.FlatQTY * o.FOT_NCC)--(o.FOT_NCC * o.BasisQTY)--#(lf)        ELSE QuantityLeft*o.FotPrice #(lf)    END AS LineTotalFlatValueBalanceFOTUSD,#(lf)    CASE #(lf)        WHEN o.PremiumFlag = 1 THEN (o.FOT_NCC * o.FlatQTY)#(lf)        ELSE QuantityLeft*o.FotPrice #(lf)    END AS LineTotalFlatBalanceFOTUSD,#(lf)#(lf)    CASE #(lf)        WHEN o.PremiumFlag = 1 #(lf)             THEN (o.CFFLAT_NCC * o.BasisQTY) + (o.CFFLAT_CC * o.FlatQTY)#(lf)        ELSE (o.CFFlat * o.OriginalQty)#(lf)    END AS LineTotalFlatValueCFFUSD,#(lf)    #(lf)    -- Combined calculation for FOT pricing#(lf)    CASE #(lf)        WHEN o.PremiumFlag = 1 #(lf)             THEN (o.FOT_NCC * o.BasisQTY) + (o.FOT_CC * o.FlatQTY)#(lf)        ELSE (o.FotPrice * o.OriginalQty)#(lf)    END AS LineTotalFlatValueFOTUSD,#(lf)#(lf)#(tab)-- Priced quantity: zeroed on rows whose paired price hasn't landed yet, so averages aren't diluted by unpriced rows#(lf)#(tab)CASE#(lf)#(tab)#(tab)WHEN o.PremiumFlag = 1 THEN CASE WHEN ISNULL(FinalPriceClosedContract,0) = 0 THEN 0 ELSE o.Quantity END#(lf)#(tab)#(tab)ELSE CASE WHEN ISNULL(o.UnitNetPriceUSD,0) = 0 THEN 0 ELSE o.Quantity END#(lf)#(tab)END AS PricedQuantity,#(lf)#(tab)CASE#(lf)#(tab)#(tab)WHEN o.PremiumFlag = 1 AND ISNULL(MarketTempPrice,0) <> 0 THEN o.BasisQTY#(lf)#(tab)#(tab)ELSE 0#(lf)#(tab)END AS PricedBasisQTY,#(lf)#(tab)CASE#(lf)#(tab)#(tab)WHEN o.PremiumFlag = 1 THEN CASE WHEN ISNULL(FinalPriceClosedContract,0) = 0 THEN 0 ELSE o.FlatQTY END#(lf)#(tab)#(tab)ELSE CASE WHEN ISNULL(o.UnitNetPriceUSD,0) = 0 THEN 0 ELSE o.FlatQTY END#(lf)#(tab)END AS PricedFlatQTY,#(lf)#(tab)-- CF-specific priced quantity: a row can have a valid Order/FOT price but a blank/zero CF price, so CF averages need their own zero-check#(lf)#(tab)CASE#(lf)#(tab)#(tab)WHEN o.PremiumFlag = 1 THEN CASE WHEN ISNULL(o.CFFLAT_CC,0) = 0 THEN 0 ELSE o.Quantity END#(lf)#(tab)#(tab)ELSE CASE WHEN ISNULL(o.CFFlat,0) = 0 THEN 0 ELSE o.Quantity END#(lf)#(tab)END AS PricedQuantityCF,#(lf)#(tab)-- FOT-specific priced quantity: same idea for the FOT price view#(lf)#(tab)CASE#(lf)#(tab)#(tab)WHEN o.PremiumFlag = 1 THEN CASE WHEN ISNULL(o.FOT_CC,0) = 0 THEN 0 ELSE o.Quantity END#(lf)#(tab)#(tab)ELSE CASE WHEN ISNULL(o.FotPrice,0) = 0 THEN 0 ELSE o.Quantity END#(lf)#(tab)END AS PricedQuantityFOT,#(lf)#(tab)-- Combined open-quantity (Basis+Flat as QuantityLeft on non-premium rows) zeroed per price type, to match LineTotalFlatValueBalanceCFFUSD/FOTUSD's own grain#(lf)#(tab)CASE#(lf)#(tab)#(tab)WHEN o.PremiumFlag = 1 THEN CASE WHEN ISNULL(o.CFFLAT_NCC,0) = 0 THEN 0 ELSE o.BasisQTY+o.FlatQTY END#(lf)#(tab)#(tab)ELSE CASE WHEN ISNULL(o.CFFlat,0) = 0 THEN 0 ELSE o.QuantityLeft END#(lf)#(tab)END AS PricedOpenQtyCF,#(lf)#(tab)CASE#(lf)#(tab)#(tab)WHEN o.PremiumFlag = 1 THEN CASE WHEN ISNULL(o.FOT_NCC,0) = 0 THEN 0 ELSE o.BasisQTY+o.FlatQTY END#(lf)#(tab)#(tab)ELSE CASE WHEN ISNULL(o.FotPrice,0) = 0 THEN 0 ELSE o.QuantityLeft END#(lf)#(tab)END AS PricedOpenQtyFOT,#(lf)#(lf)#(tab)CASE#(lf)#(tab)#(tab)WHEN o.[סטטוס] = 1 then 'Open Order'#(lf)#(tab)#(tab)else null#(lf)#(tab)END AS 'Open_Slicer'#(lf)#(lf)/*#(tab)#(tab),CASE#(lf)#(tab)#(tab)#(tab)WHEN o.PremiumFlag = 1 THEN o.LineTotalFlatValueBalanceCFFUSD + LineTotalCF_USD#(lf)#(tab)#(tab)#(tab)ELSE LineTotalCF_USD END#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)AS LineTotalFlatValueCFFUSD#(lf)#(tab)#(tab),CASE#(lf)#(tab)#(tab)#(tab)WHEN o.PremiumFlag = 1 THEN o.LineTotalFlatValueBalanceFOTUSD + LineTotalCF_USD#(lf)#(tab)#(tab)#(tab)ELSE LineTotalCF_USD END#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)#(tab)AS LineTotalFlatValueFOTUSD#(lf)*/#(lf)#(lf)FROM Orders o#(lf)where 1=1#(lf)--and OrderID = 140452#(lf)--and BasisQTY is not null#(lf)--and BasisQTY <>0#(lf))#(lf)#(lf)-- Step 1: materialise the base exactly as v1 did (no join) - this is the fast path.#(lf)SELECT ItemKey, OrderID, [Date], OrderCreateTime,#(lf)       PricedQuantity, PricedQuantityCF, PricedQuantityFOT,#(lf)       LineTotalFlatValueUSD, LineTotalFlatValueCFFUSD, LineTotalFlatValueFOTUSD#(lf)INTO #raw FROM ordersBase;#(lf)#(lf)-- Step 2: attach the Article and drop unmapped items.#(lf)SELECT am.Article_Description AS Article, r.OrderID, r.[Date], r.OrderCreateTime,#(lf)       r.PricedQuantity, r.PricedQuantityCF, r.PricedQuantityFOT,#(lf)       r.LineTotalFlatValueUSD, r.LineTotalFlatValueCFFUSD, r.LineTotalFlatValueFOTUSD#(lf)INTO #ob#(lf)FROM #raw r#(lf)JOIN #am am ON am.ItemKey = r.ItemKey#(lf)WHERE am.Article_Description <> 'Other';#(lf)CREATE CLUSTERED INDEX ix_ob ON #ob(Article, OrderCreateTime DESC, OrderID DESC);#(lf)#(lf)WITH Steps as (#(lf)    SELECT TOP (20)#(lf)           500 * CAST(ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS int) AS Step#(lf)    FROM sys.all_objects#(lf))#(lf)#(lf)/* One tail per (Article, price type). Pooled across every ItemKey in the#(lf)   Article, so ""last 500 of Corn"" is 500 units, not 500 per item. */#(lf),OrdersLong as (#(lf)    SELECT 1 AS PriceTypeID, Article, OrderID, [Date], OrderCreateTime,#(lf)           PricedQuantity AS PricedQty, LineTotalFlatValueUSD AS LineValueUSD#(lf)    FROM #ob#(lf)    UNION ALL#(lf)    SELECT 2, Article, OrderID, [Date], OrderCreateTime, PricedQuantityCF, LineTotalFlatValueCFFUSD FROM #ob#(lf)    UNION ALL#(lf)    SELECT 3, Article, OrderID, [Date], OrderCreateTime, PricedQuantityFOT, LineTotalFlatValueFOTUSD FROM #ob#(lf))#(lf)#(lf),Priced as (#(lf)    SELECT PriceTypeID, Article, OrderID, [Date], OrderCreateTime, PricedQty, LineValueUSD,#(lf)           LineValueUSD / PricedQty AS UnitPriceUSD#(lf)    FROM OrdersLong#(lf)    WHERE ISNULL(PricedQty, 0) > 0 AND LineValueUSD IS NOT NULL#(lf))#(lf)#(lf),Tail as (#(lf)    SELECT p.*,#(lf)           ISNULL(SUM(p.PricedQty) OVER (PARTITION BY p.PriceTypeID, p.Article#(lf)                ORDER BY p.OrderCreateTime DESC, p.OrderID DESC#(lf)                ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0) AS RunQtyBefore,#(lf)           SUM(p.PricedQty) OVER (PARTITION BY p.PriceTypeID, p.Article#(lf)                ORDER BY p.OrderCreateTime DESC, p.OrderID DESC#(lf)                ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)     AS RunQtyAfter,#(lf)           ISNULL(SUM(p.LineValueUSD) OVER (PARTITION BY p.PriceTypeID, p.Article#(lf)                ORDER BY p.OrderCreateTime DESC, p.OrderID DESC#(lf)                ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0) AS RunValBefore#(lf)    FROM Priced p#(lf))#(lf)#(lf),TailPruned as ( SELECT * FROM Tail WHERE RunQtyBefore < 10000 )#(lf)#(lf),TailTotal as (#(lf)    SELECT PriceTypeID, Article,#(lf)           MAX(RunQtyAfter)                 AS TotalQty,#(lf)           MAX(RunValBefore + LineValueUSD) AS TotalValue#(lf)    FROM Tail GROUP BY PriceTypeID, Article#(lf))#(lf)#(lf)/* Long form: one row per (Article, Step, price type). Pivoted below. */#(lf),Stepped as (#(lf)    SELECT k.Article, k.PriceTypeID, s.Step,#(lf)           CASE WHEN b.OrderID IS NULL THEN tt.TotalQty ELSE s.Step END AS Qty,#(lf)           CASE WHEN b.OrderID IS NULL THEN tt.TotalValue#(lf)                ELSE b.RunValBefore + (s.Step - b.RunQtyBefore) * b.UnitPriceUSD#(lf)           END AS Val,#(lf)           b.OrderID          AS BoundaryOrderID,#(lf)           b.[Date]           AS BoundaryOrderDate,#(lf)           b.OrderCreateTime  AS BoundaryOrderCreateTime,#(lf)           CASE WHEN b.OrderID IS NULL THEN NULL#(lf)                ELSE s.Step - b.RunQtyBefore END AS BoundaryQtyTaken#(lf)    FROM (SELECT DISTINCT PriceTypeID, Article FROM TailPruned) k#(lf)    JOIN Steps s ON 1 = 1#(lf)    LEFT JOIN TailPruned b#(lf)           ON b.PriceTypeID = k.PriceTypeID AND b.Article = k.Article#(lf)          AND b.RunQtyBefore < s.Step AND b.RunQtyAfter >= s.Step#(lf)    LEFT JOIN TailTotal tt#(lf)           ON tt.PriceTypeID = k.PriceTypeID AND tt.Article = k.Article#(lf))#(lf)#(lf)/* Pivot the three price types onto one row per (Article, Step).#(lf)   Each keeps its own tail, so quantities can differ where a price is missing. */#(lf)SELECT#(lf)     Article#(lf)    ,Step#(lf)    -- Single shared quantity: the Order-view unit count, used as the divisor#(lf)    -- for all three price views (per decision). Note: on articles where a CIF#(lf)    -- or FOT price is missing from some rows, that view's tail covers fewer#(lf)    -- units than QtyOrder counts, so its average is understated. As of the#(lf)    -- last check this affects Oils only (FOT gap up to ~3,368 units); BPP has#(lf)    -- no CIF prices at all so its CIF column is blank regardless.#(lf)    ,CAST(MAX(CASE WHEN PriceTypeID=1 THEN Qty END) AS decimal(19,5)) AS Qty#(lf)    ,CAST(MAX(CASE WHEN PriceTypeID=1 THEN Val END) AS decimal(19,6)) AS ValueOrderUSD#(lf)    ,CAST(MAX(CASE WHEN PriceTypeID=2 THEN Val END) AS decimal(19,6)) AS ValueCIFUSD#(lf)    ,CAST(MAX(CASE WHEN PriceTypeID=3 THEN Val END) AS decimal(19,6)) AS ValueFOTUSD#(lf)    -- audit: boundary order for the Order price view#(lf)    ,MAX(CASE WHEN PriceTypeID=1 THEN BoundaryOrderID   END) AS BoundaryOrderID#(lf)    ,MAX(CASE WHEN PriceTypeID=1 THEN BoundaryOrderDate END) AS BoundaryOrderDate#(lf)    ,MAX(CASE WHEN PriceTypeID=1 THEN BoundaryOrderCreateTime END) AS BoundaryOrderCreateTime#(lf)    ,CAST(MAX(CASE WHEN PriceTypeID=1 THEN BoundaryQtyTaken END) AS decimal(19,5)) AS BoundaryQtyTaken#(lf)    /* Step status, for the matrix:#(lf)         'Full'    - the step reached its full N units#(lf)         'Partial' - the article's entire priced history is shorter than N, so#(lf)                     Qty is the true total (e.g. 9,740 against a 10,000 step)#(lf)       A NULL boundary order is exactly the signal that the tail ran out. */#(lf)    ,CASE WHEN MAX(CASE WHEN PriceTypeID=1 THEN BoundaryOrderID END) IS NULL#(lf)          THEN 'Partial' ELSE 'Full' END AS StepStatus#(lf)    /* Row label. A partial step is labelled with its REAL total, so the axis#(lf)       reads ""Last 9,740 (all)"" rather than a ""10,000"" that was never reached. */#(lf)    ,CASE WHEN MAX(CASE WHEN PriceTypeID=1 THEN BoundaryOrderID END) IS NULL#(lf)          THEN 'Last ' + FORMAT(MAX(CASE WHEN PriceTypeID=1 THEN Qty END), 'N0') + ' (all)'#(lf)          ELSE 'Last ' + FORMAT(Step, 'N0')#(lf)     END AS StepLabel#(lf)    ,GETDATE() AS RowInsertDatetime#(lf)FROM Stepped#(lf)GROUP BY Article, Step#(lf)/* Keep every full step, plus the FIRST partial one (the article's true total).#(lf)   Without this an article with 3,394 units emits 14 identical rows from 3,500#(lf)   to 10,000, padding the matrix with repeats of the same number. */#(lf)HAVING MAX(CASE WHEN PriceTypeID=1 THEN BoundaryOrderID END) IS NOT NULL#(lf)    OR Step = (SELECT MIN(s2.Step) FROM Stepped s2#(lf)               WHERE s2.Article = Stepped.Article AND s2.PriceTypeID = 1#(lf)                 AND s2.BoundaryOrderID IS NULL)#(lf)ORDER BY Article, Step#(lf)"])
